mapper.sql:
WHERE 1 = 1

    AND t.id = #{query.traceId}


    AND t.user_id = #{query.userId}


    AND t.username ILIKE CONCAT('%', #{query.username}, '%')


    AND (t.session_id = #{query.sessionId} OR t.python_session_id = #{query.sessionId})


    AND t.request_id = #{query.requestId}


    AND t.business_type = #{query.businessType}


    AND t.entrypoint = #{query.entrypoint}


    AND t.status = #{query.status}


    AND EXISTS (
        SELECT 1
        FROM t_ai_llm_call fc
        WHERE fc.trace_id = t.id



    )


    AND t.started_at >= #{query.startedFrom}


    AND t.started_at <= #{query.startedTo}

mapper.select:
SELECT t.id, t.request_id, t.user_id, t.username, t.session_id, t.python_session_id, t.business_type, t.entrypoint, t.status, t.error_code, t.error_message, t.started_at, t.ended_at, t.duration_ms, t.created_at, COALESCE(step_counts.step_count, 0) AS step_count, COALESCE(llm_counts.llm_call_count, 0) AS llm_call_count, COALESCE(llm_counts.total_tokens, 0) AS total_tokens, COALESCE(llm_counts.failed_llm_calls, 0) AS failed_llm_calls, COALESCE(llm_counts.fallback_used, FALSE) AS fallback_used, llm_counts.provider, llm_counts.model, llm_counts.provider_prompt_cache_token_hit_rate, llm_counts.provider_prompt_cache_call_hit_rate FROM t_ai_trace t LEFT JOIN ( SELECT trace_id, COUNT(*) AS step_count FROM t_ai_trace_step GROUP BY trace_id ) step_counts ON step_counts.trace_id = t.id LEFT JOIN ( SELECT trace_id, COUNT(*) AS llm_call_count, STRING_AGG(DISTINCT lc.provider, ', ' ORDER BY lc.provider) AS provider, STRING_AGG(DISTINCT lc.model, ', ' ORDER BY lc.model) AS model, COALESCE(SUM(total_tokens), 0) AS total_tokens, COUNT(*) FILTER (WHERE status <> 'SUCCESS') AS failed_llm_calls, BOOL_OR(fallback_used) AS fallback_used, CASE WHEN SUM( CASE WHEN lc.cache_reported_by_provider THEN COALESCE(lc.prompt_cache_hit_tokens, 0) + COALESCE(lc.prompt_cache_miss_tokens, 0) ELSE 0 END ) > 0 THEN ROUND( SUM( CASE WHEN lc.cache_reported_by_provider THEN COALESCE(lc.prompt_cache_hit_tokens, 0) ELSE 0 END )::NUMERIC / SUM( CASE WHEN lc.cache_reported_by_provider THEN COALESCE(lc.prompt_cache_hit_tokens, 0) + COALESCE(lc.prompt_cache_miss_tokens, 0) ELSE 0 END )::NUMERIC, 6 ) ELSE NULL END AS provider_prompt_cache_token_hit_rate, CASE WHEN COUNT(*) FILTER (WHERE lc.cache_reported_by_provider) > 0 THEN ROUND( COUNT(*) FILTER ( WHERE lc.cache_reported_by_provider AND COALESCE(lc.prompt_cache_hit_tokens, 0) > 0 )::NUMERIC / COUNT(*) FILTER (WHERE lc.cache_reported_by_provider)::NUMERIC, 6 ) ELSE NULL END AS provider_prompt_cache_call_hit_rate FROM t_ai_llm_call lc WHERE 1 = 1
GROUP BY trace_id ) llm_counts ON llm_counts.trace_id = t.id
ORDER BY t.started_at DESC, t.created_at DESC, t.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT id AS call_id, trace_id, prompt_text, response_text
FROM t_ai_llm_call
WHERE id = #{callId}
